sys_variable_value.value:
(function execute(inputs, outputs) {
    // ... code ... 
    var inputsPayload = {};
    // supplier_case is a input of type: glide_record
    inputsPayload['input'] = inputs.markdown;


    var capabilityId = '25fa89553b3bae10cb98111864e45a49';
    var request = {
        executionRequests: [{
            payload: inputsPayload,
            capabilityId: capabilityId,
            meta: {
                skillConfigId: 'dafa41953b3bae10cb98111864e45a94'
            }
        }],
        mode: 'sync'
    };

    try {
        var response = sn_one_extend.OneExtendUtil.execute(request) || {};
        var skillResponse = ((response["capabilities"] || {})[capabilityId] || {})["response"];
        var result = JSON.parse(skillResponse);
        gs.info(result.model_output);
        outputs.status = '200';
        outputs.output = result.model_output;
       // gs.addInfoMessage(JSON.stringify(skillResponse));

    } catch (e) {
        gs.error(e);
        gs.info('Something went wrong while executing skill.');
    }
    
})(inputs, outputs);

