sys_variable_value.value:
(function execute(inputs, outputs) {

    var useridentity = JSON.parse(inputs.input);   

    var gr = new GlideRecord('x_vuram_financia_0_fcc_kyc_individual_details');
    if (gr.get(inputs.sysId)) { 
        gr.poi_doc_name = useridentity.doc_name;
        
        var gd = new GlideDate();
        gd.setValue(useridentity.dob);  // Works in scoped apps
        gr.dob = gd;

        gr.poi_identity_doc_type = useridentity.document_type;
        gr.poi_doc_issued_by = useridentity.doc_issued_by;
        gr.poi_doc_issued_date = useridentity.doc_issued_date;
        gr.poi_doc_id_no = useridentity.doc_id_no;  
        gr.poi_doc_expiry_date = useridentity.doc_expiry_date;
        gr.poi_doc_place_of_issuance = useridentity.doc_place_of_issuance;
        gr.update();
    } else {
        gs.error('No record found with sys_id: ' + inputs.sys_parm);
    }

})(inputs, outputs);

